(function(){
"use strict";
const P=window.PM;if(!P||!P.unit)return;const U=P.unit,R=P.R,S=P.S;

/* 1 ─ My family */
U({id:'o01',title:'My family',strand:'Traditions and Celebrations',codes:['A1','A3'],
 guide:{goal:'Describe a family, name family members, and put important family events on a timeline.',words:'family, relative, generation, timeline, born, married',ask:['Who is in your family?','What is a timeline?','What happened before you were born?'],home:'Ask a grandparent or older relative about one special event. Add it to a family timeline with the year.'},
 watch:['Line up the years!','First Grandpa was born, then Dad was born, then you were born.'],
 fig:'Family members on a timeline, from long ago to now.',
 page:{story:{title:'Amira’s Family Tree',text:'Amira made a *family tree* for school. At the top she drew *Grandpa* and *Grandma*, who got married a long time ago. Next she drew *Dad*, *Aunt Sara* and *Uncle Ali*. Then she drew *Mom*, her baby *brother*, and herself. Her *cousins* went on a branch beside her. "Families come in all shapes and sizes," said her teacher. "Some are big, some are small, and every one is special."',pics:['grandpa','grandma','family','baby']},
  boxes:[{title:'Family words',ex:[['woman','mom'],['man','dad'],['grandma','grandma'],['grandpa','grandpa'],['girl','sister'],['boy','brother'],['woman','aunt'],['child','cousin']]},
   {title:'A family timeline',text:'A *timeline* shows events in the *order* they happened, from long ago to now.',lines:['Grandpa was born','Grandpa and Grandma got married','Dad was born','Dad and Mom got married','*I was born!*'],cols:1}],
  cards:[{q:'Your parent’s sister is your…',a:'*aunt*'},{q:'Your aunt’s child is your…',a:'*cousin*'}],
  words:[['family','people who love and care for each other'],['timeline','a line that shows events in order']]},
 steps:[
  {say:'Read the story',speech:'Amira made a family tree. At the top she drew Grandpa and Grandma. Next she drew Dad, Aunt Sara and Uncle Ali. Then she drew Mom, her baby brother and herself. Families come in all shapes and sizes.',set:S.row(['grandpa','grandma','family','baby'],{labels:['Grandpa','Grandma','Dad and Mom','baby brother']}),
   cues:[['Grandpa','grandpa','Grandpa'],['Grandma','grandma','Grandma'],['Dad','family','parents'],['baby brother','baby','brother']]},
  {say:'A timeline',speech:'A timeline goes from long ago to now. First, Grandpa was born. Then Dad was born. Then you were born!',set:S.order(['grandpa','man','baby']),
   cues:[['Grandpa was born','grandpa','long ago'],['Dad was born','man','later'],['you were born','baby','now','play']]},
  {say:'Generations',speech:'Each step down the family tree is a new generation: grandparents, then parents, then children.',set:S.row(['grandma','woman','child'],{labels:['grandparents','parents','children']}),
   cues:[['grandparents','grandma','1st'],['parents','woman','2nd'],['children','child','3rd']]},
  {say:'All kinds of families',speech:'Some families have two parents. Some have one. Some live with grandparents, aunts or uncles. Every family is special.',set:S.row(['family','woman','grandpa','people'],{labels:['two parents','one parent','grandparents','big family']}),
   cues:[['two parents','family','family'],['live with grandparents','grandpa','family'],['Every family is special','people','special']]}],
 more:{title:'Did you know?',text:'Some families keep a *family quilt*. Each person adds a square, made from an old baby blanket, a favourite shirt or a scarf. Over many years, the quilt becomes a *timeline* you can wrap yourself in!',pics:['scarf','shirt','baby','heart'],lead:'A family fact!'},
 rounds:[R.order('Put the timeline in order: tap 1, 2, 3.',['grandpa','man','baby']),R.q('Your mom’s mother is your…',['grandma','aunt','cousin'],'grandma'),
  R.q('Your dad’s brother is your…',['uncle','grandpa','cousin'],'uncle'),R.q('Your uncle’s child is your…',['cousin','sister','aunt'],'cousin'),
  R.q('What does a timeline show?',['events in order','the weather','a map'],'events in order'),R.q('Which event comes *first*?',['Grandpa was born','I was born','Dad was born'],'Grandpa was born'),
  R.q('Which event comes *last* on Amira’s timeline?',['Amira was born','Grandma got married','Dad was born'],'Amira was born'),R.q('Who did Amira draw at the top of her tree?',['Grandpa and Grandma','her cousins','her teacher'],'Grandpa and Grandma'),
  R.tf('All families are the same size.',false),R.q('Grandparents, parents and children are three…',['generations','cities','seasons'],'generations'),
  R.q('In "Did you know?", what does each person add to a family quilt?',['a square','a button','a photo'],'a square'),R.q('Who is a relative?',['an aunt','a bus driver','a mail carrier'],'an aunt')],
 tries:[['Name someone in your family.','*my grandma*, *my brother*…'],['What year were you born?','*20__*: put it on your timeline!']]});

/* 2 ─ Celebrations around the world */
U({id:'o02',title:'Celebrations of many cultures',strand:'Traditions and Celebrations',codes:['A1','A2'],
 guide:{goal:'Name celebrations from different cultures (Eid al-Fitr, Powwow, Hanukkah, Lunar New Year) and explain why traditions are important to families.',words:'culture, tradition, celebration, festival, Eid al-Fitr, powwow, Hanukkah, Lunar New Year',ask:['What celebrations does your family have?','What is a tradition?','How are celebrations alike?'],home:'Ask your family: What is our favourite celebration? What do we always do?'},
 watch:['So many celebrations!','Families celebrate with food, music, lights and time together.'],
 fig:'Celebrations from many cultures.',
 page:{story:{title:'The Class Celebration Calendar',text:'Our class made a *celebration calendar*. Hamza told us about *Eid al-Fitr*: after a month of fasting, his family wears new clothes, visits friends and shares sweets. Ruth told us about *Hanukkah*: her family lights a candle each night for eight nights. Kai showed photos of a *powwow*, with drums, singing and colourful regalia. Lin told us about *Lunar New Year*, with dumplings and a dragon dance!',pics:['moon','candle','drum','dragon']},
  boxes:[{title:'Celebrations of many cultures',ex:[['moon','*Eid al-Fitr*'],['candle','*Hanukkah*'],['drum','*Powwow*'],['dragon','*Lunar New Year*']]},
   {title:'How celebrations are alike',ex:[['cake','special food'],['music','music'],['family','family and friends'],['gift','gifts or treats']]}],
  cards:[{q:'What is a tradition?',a:'something a family or group *does again and again*, often for many years'},{q:'Name a celebration with a dragon dance.',a:'*Lunar New Year*'}],
  words:[['tradition','a custom passed down over time'],['culture','the way of life of a group of people']]},
 steps:[
  {say:'Read the story',speech:'Hamza told us about Eid al-Fitr: his family wears new clothes and shares sweets. Ruth told us about Hanukkah: a candle each night for eight nights. Kai showed a powwow, with drums and singing. Lin told us about Lunar New Year, with dumplings and a dragon dance!',set:S.row(['moon','candle','drum','dragon'],{labels:['Eid al-Fitr','Hanukkah','Powwow','Lunar New Year']}),
   cues:[['Eid al-Fitr','moon','Eid'],['Hanukkah','candle','Hanukkah'],['a powwow','drum','Powwow'],['Lunar New Year','dragon','New Year']]},
  {say:'What is a tradition?',speech:'A tradition is something a family or a group does again and again, often passed down from grandparents to parents to children.',set:S.order(['grandma','woman','child']),
   cues:[['passed down','grandma','tradition'],['to children','child','you!','play']]},
  {say:'Alike and different',speech:'Celebrations are different, but many are alike. They have special food, music, family and friends, and sometimes gifts.',set:S.row(['cake','music','family','gift']),
   cues:[['special food','cake','food'],['music','music','music'],['family and friends','family','together'],['gifts','gift','gifts']]},
  {say:'Your celebration',speech:'What celebration is important to your family? Think of a song, a food or something you always do together.',set:S.row(['party','music','cake'],{labels:['my celebration','our song','our food']}),
   cues:[['a song','music','song'],['a food','cake','food']]}],
 more:{title:'Did you know?',text:'Canada is home to people from more than *200* different cultures! That means in one city, you might see fireworks for *Diwali*, a dragon parade for *Lunar New Year*, a *powwow* and a *Christmas* concert, all in the same year.',pics:['canada','fire','dragon','music'],lead:'A Canada fact!'},
 rounds:[R.q('Which celebration has a *dragon dance*?',['Lunar New Year','Hanukkah','Eid al-Fitr'],'Lunar New Year',{set:{row:['dragon'],keep:true}}),R.q('Which celebration lights a candle each night for *eight nights*?',['Hanukkah','Powwow','Lunar New Year'],'Hanukkah'),
  R.q('A *powwow* is a celebration of…',['First Nations peoples','the Chinese New Year','summer camp'],'First Nations peoples'),R.q('*Eid al-Fitr* is a…',['Muslim holiday','Jewish holiday','Hindu holiday'],'Muslim holiday'),
  R.q('What is a tradition?',['something done again and again over time','a new toy','a kind of car'],'something done again and again over time'),R.q('How are many celebrations alike?',['special food and family','they are all in July','they all have snow'],'special food and family'),
  R.q('What did Hamza’s family share at Eid?',['sweets','pumpkins','fireworks only'],'sweets'),R.q('What did Kai’s photos show?',['drums and singing','a dragon','candles'],'drums and singing'),
  R.tf('All families celebrate the same holidays.',false),R.q('Lunar New Year food in Lin’s story?',['dumplings','pancakes','latkes'],'dumplings'),
  R.q('In "Did you know?", how many cultures live in Canada?',['more than 200','about 5','exactly 10'],'more than 200'),R.q('Who passes traditions down?',['grandparents and parents','strangers','robots'],'grandparents and parents')],
 tries:[['Name a celebration your family has.','*birthday*, *Eid*, *Christmas*, *Diwali*…'],['Name one thing celebrations share.','*food*, *music*, *family*']]});

/* 3 ─ Traditional foods */
U({id:'o03',title:'Traditional foods',strand:'Traditions and Celebrations',codes:['A1','A2'],
 guide:{goal:'Describe traditional foods that families pass down through generations, and where they come from.',words:'heritage, recipe, traditional food, pass down, generation',ask:['What food does your family make for special days?','Who taught your family that recipe?','Where does that food come from?'],home:'Cook a family recipe together. Ask: who taught you this? Write the recipe on a card.'},
 watch:['Recipes passed down!','Grandma taught Mom, and Mom teaches you.'],
 fig:'Traditional foods from many places.',
 page:{story:{title:'The Recipe Box',text:'Leo found an old *recipe box* in Grandma’s kitchen. Inside was a card for *gnocchi*, little potato dumplings from *Italy*. "My nonna taught me," said Grandma, "and her nonna taught her." Leo’s friend Mei makes *turnip cake* with her grandpa for Lunar New Year, a recipe from *China*. Ava helps her mom fry *oliebollen*, sweet doughnuts from the *Netherlands*. Each recipe is a little piece of *heritage*.',pics:['grandma','spaghetti','pie','donut']},
  boxes:[{title:'Heritage',text:'*Heritage* is the celebrations, foods and special practices passed down in our families. Recipes are often taught from *grandparents* to *parents* to *children*.',ex:[['spaghetti','gnocchi: *Italy*'],['pie','turnip cake: *China*'],['donut','oliebollen: *the Netherlands*'],['pancakes','bannock: *First Nations*']]}],
  cards:[{q:'What makes a food *traditional*?',a:'it is made the *same way* for many generations'},{q:'Where are oliebollen from?',a:'*the Netherlands*'}],
  words:[['heritage','traditions passed down in a family or culture'],['recipe','the steps to make a food']]},
 steps:[
  {say:'Read the story',speech:'Leo found Grandma’s recipe for gnocchi, little dumplings from Italy. My nonna taught me, said Grandma. Mei makes turnip cake with her grandpa, a recipe from China. Ava fries oliebollen, sweet doughnuts from the Netherlands. Each recipe is a piece of heritage.',set:S.row(['grandma','spaghetti','pie','donut'],{labels:['Grandma','gnocchi','turnip cake','oliebollen']}),
   cues:[['gnocchi','spaghetti','Italy'],['turnip cake','pie','China'],['oliebollen','donut','Netherlands']]},
  {say:'Passed down',speech:'A recipe can travel through time. Great-grandma taught Grandma. Grandma taught Mom. Mom teaches you!',set:S.order(['grandma','woman','child']),
   cues:[['taught Grandma','grandma','long ago'],['Mom teaches you','child','now','play']]},
  {say:'Foods from many places',speech:'In Canada, families make foods from all over the world: bannock, perogies, dumplings, roti and more.',set:S.row(['pancakes','perogies','pie','bread'],{labels:['bannock','perogies','dumplings','roti']}),
   cues:[['bannock','pancakes','First Nations'],['perogies','perogies','Ukraine, Poland'],['roti','bread','India, Caribbean']]},
  {say:'Your recipe',speech:'Is there a food your family makes again and again? That food is part of your heritage!',set:S.row(['family','soup','heart'],{labels:['my family','our food','our heritage']}),
   cues:[['your heritage','heart','heritage']]}],
 more:{title:'Did you know?',text:'*Bannock* is a simple bread that many First Nations and Métis families have made for a very long time. It can be baked, fried, or cooked on a stick over a campfire. Many families have their own special way to make it.',pics:['bread','fire','stick','family'],lead:'A food fact from Canada!'},
 rounds:[R.q('Where does *gnocchi* come from?',['Italy','China','Mexico'],'Italy'),R.q('Where does *turnip cake* in the story come from?',['China','Italy','the Netherlands'],'China'),
  R.q('*Oliebollen* are sweet doughnuts from…',['the Netherlands','Japan','Canada'],'the Netherlands',{set:{row:['donut'],keep:true}}),R.q('What is *heritage*?',['traditions passed down in a family','a new phone','a type of weather'],'traditions passed down in a family'),
  R.order('Who taught whom? Put them in order.',['grandma','woman','child']),R.q('Who taught Grandma to make gnocchi?',['her nonna','her teacher','a TV show'],'her nonna'),
  R.q('When does Mei make turnip cake?',['for Lunar New Year','for Halloween','every Monday'],'for Lunar New Year'),R.q('What did Leo find in Grandma’s kitchen?',['a recipe box','a cat','a map'],'a recipe box'),
  R.tf('A traditional food is made the same way for many years.',true),R.q('Bannock can be cooked…',['on a stick over a campfire','only in a freezer','in a washing machine'],'on a stick over a campfire'),
  R.q('In "Did you know?", which families have made bannock for a long time?',['First Nations and Métis families','pirates','astronauts'],'First Nations and Métis families'),R.q('Which is a recipe?',['the steps to make a food','a song','a map'],'the steps to make a food')],
 tries:[['Name a food your family makes for celebrations.','*cake*, *tamales*, *biryani*, *turkey*…'],['Who could teach you a family recipe?','a *grandparent*, a *parent*, an *aunt*']]});

/* 4 ─ Festivals of light */
U({id:'o04',title:'Festivals of light',strand:'Traditions and Celebrations',codes:['A1','A2'],
 guide:{goal:'Learn about Diwali and Hanukkah, two festivals of light, and compare what people do and eat.',words:'Diwali, diya, Hanukkah, menorah, latkes, sufganiyot, kheer, compare',ask:['Why are Diwali and Hanukkah called festivals of light?','What is a menorah?','How are the two festivals alike?'],home:'Make a chart comparing two celebrations your class talked about: name, when, what people do, what they eat.'},
 watch:['Light up the night!','Diwali lamps glow, and Hanukkah candles are lit one more each night.'],
 fig:'Lamps and candles of two festivals of light.',
 page:{story:{title:'Two Festivals, Lots of Light',text:'In *October or November*, Priya’s family celebrates *Diwali*, the Festival of Lights. They put little clay lamps called *diyas* all around the house to show that *light wins over darkness*. They eat *kheer*, a milky rice pudding, and coconut sweets. In *November or December*, Noah’s family celebrates *Hanukkah* for *eight days*. Each night they light one more candle in a *menorah*. They eat *latkes* (potato pancakes) and *sufganiyot* (jelly doughnuts).',pics:['candle','fire','pancakes','donut']},
  boxes:[{title:'Compare',lines:['*Diwali*: Festival of Lights · *Hanukkah*: Festival of Lights','*Diwali*: Hindu, Sikh, Jain · *Hanukkah*: Jewish','*Diwali*: five days · *Hanukkah*: eight days','*Diwali*: diyas, fireworks · *Hanukkah*: menorah candles','*Diwali*: kheer, sweets · *Hanukkah*: latkes, sufganiyot'],cols:1}],
  cards:[{q:'How many branches does a Hanukkah menorah have?',a:'*nine*: eight candles and one helper candle'},{q:'What are diyas?',a:'little *clay lamps* for Diwali'}],
  words:[['festival','a big celebration'],['compare','find how things are alike and different']]},
 steps:[
  {say:'Read the story',speech:'Priya’s family celebrates Diwali, the Festival of Lights, with little clay lamps called diyas, to show that light wins over darkness. Noah’s family celebrates Hanukkah for eight days, lighting one more candle each night in a menorah.',set:S.row(['fire','candle'],{labels:['Diwali diyas','Hanukkah menorah']}),
   cues:[['Diwali','fire','Diwali'],['Hanukkah','candle','Hanukkah']]},
  {say:'Diwali',speech:'Diwali lasts five days in October or November. Families light diyas, decorate with colourful patterns, set off fireworks, and share kheer and sweets.',set:S.row(['fire','sparkles','rice'],{labels:['diyas','fireworks','kheer']}),
   cues:[['light diyas','fire','lamps'],['fireworks','sparkles','fireworks'],['kheer','rice','rice pudding']]},
  {say:'Hanukkah',speech:'Hanukkah lasts eight days. Families light the menorah, play a spinning top game, and eat latkes and sufganiyot.',set:S.row(['candle','pancakes','donut'],{labels:['menorah','latkes','sufganiyot']}),
   cues:[['light the menorah','candle','8 nights'],['latkes','pancakes','potato pancakes'],['sufganiyot','donut','jelly doughnuts']]},
  {say:'Alike and different',speech:'Both are festivals of light, with special foods and family. They are different in when they happen, how long they last and what people eat.',set:S.sort(['Diwali','Hanukkah'],[['fire',0,'diyas'],['candle',1,'menorah'],['rice',0,'kheer'],['pancakes',1,'latkes']]),
   cues:[['Both are festivals of light','bin:Diwali','light'],['different','bin:Hanukkah','compare','play']]}],
 more:{title:'Did you know?',text:'During Diwali, many families make *rangoli*: bright patterns on the floor made of coloured powder, rice or flower petals. Rangoli welcome guests and good luck into the home.',pics:['blossom','rice','house','sparkles'],lead:'A celebration fact!'},
 rounds:[R.q('Diwali is known as the Festival of…',['Lights','Kites','Harvest'],'Lights'),R.q('What are *diyas*?',['little clay lamps','potato pancakes','dragon masks'],'little clay lamps'),
  R.q('How many days does Hanukkah last?',['eight','one','twelve'],'eight'),R.q('What do families light during Hanukkah?',['a menorah','a pumpkin','a bonfire'],'a menorah',{set:{row:['candle'],keep:true}}),
  R.q('*Latkes* are…',['potato pancakes','rice pudding','sweet drinks'],'potato pancakes'),R.q('*Kheer* is a…',['milky rice pudding','jelly doughnut','dumpling'],'milky rice pudding'),
  R.sort('Which festival?',['Diwali','Hanukkah'],[['fire',0,'diyas'],['candle',1,'menorah'],['rice',0,'kheer'],['donut',1,'sufganiyot']]),R.q('Diwali lamps show that…',['light wins over darkness','winter is coming','school is over'],'light wins over darkness'),
  R.q('When is Diwali usually celebrated?',['October or November','June','March'],'October or November'),R.tf('Diwali and Hanukkah are both festivals of light.',true),
  R.q('In "Did you know?", what are rangoli?',['bright floor patterns','candles','songs'],'bright floor patterns'),R.q('How many branches does a Hanukkah menorah have?',['nine','three','five'],'nine')],
 tries:[['Name a food for Diwali.','*kheer*, *coconut sweets*'],['Name a food for Hanukkah.','*latkes*, *sufganiyot*']]});

/* 5 ─ Cultural communities in Canada */
U({id:'o05',title:'Cultures in our communities',strand:'Traditions and Celebrations',codes:['A1','A2','A3'],
 guide:{goal:'Explore cultural neighbourhoods in Canadian cities (Chinatown, Little Italy, Greektown, Little India) and compare family foods with a Venn diagram.',words:'community, neighbourhood, culture, Venn diagram, both',ask:['What is a cultural neighbourhood?','What can you buy in Chinatown?','What foods do you and a friend both eat?'],home:'Visit a grocery store aisle with foods from around the world. Pick one new food to try.'},
 watch:['Shop around the world!','In one city, you can visit Chinatown, Little Italy and Greektown.'],
 fig:'Neighbourhoods and the foods and things you find there.',
 page:{story:{title:'A Day in the City',text:'On Saturday, Sofia and her dad explored the city. In *Chinatown*, they bought bowls, chopsticks and bok choy. In *Little Italy*, they shared a slice of pizza. In *Greektown*, they tried souvlaki on a stick. In *Little India*, Sofia saw beautiful *saris* in every colour. "In Canada, we can keep our own traditions *and* enjoy other people’s too," Dad said. "That makes our country interesting!"',pics:['bowl','pizza','meat','dress']},
  boxes:[{title:'Cultural neighbourhoods',ex:[['bowl','*Chinatown*'],['pizza','*Little Italy*'],['meat','*Greektown*'],['dress','*Little India*']]},
   {title:'A Venn diagram',text:'A *Venn diagram* has two circles. Things that belong to *both* go in the middle where the circles overlap.',lines:['My family: rice, tortillas, *bread*','My friend’s family: naan, pasta, *bread*','Both: *bread*']}],
  cards:[{q:'What goes in the middle of a Venn diagram?',a:'things that are in *both* groups'},{q:'Why is Canada an interesting place to live?',a:'many *cultures* share their traditions'}],
  words:[['community','a group of people who live, work or share things together'],['Venn diagram','two circles that show alike and different']]},
 steps:[
  {say:'Read the story',speech:'In Chinatown, Sofia and her dad bought bowls and chopsticks. In Little Italy, they shared pizza. In Greektown, they tried souvlaki. In Little India, Sofia saw beautiful saris. In Canada, we can keep our own traditions and enjoy others too.',set:S.row(['bowl','pizza','meat','dress'],{labels:['Chinatown','Little Italy','Greektown','Little India']}),
   cues:[['Chinatown','bowl','bowls'],['Little Italy','pizza','pizza'],['Greektown','meat','souvlaki'],['Little India','dress','saris']]},
  {say:'Match the shop',speech:'Match each thing to its neighbourhood. Chopsticks go to Chinatown. Pizza goes to Little Italy.',set:S.sort(['Chinatown','Little Italy'],[['bowl',0,'chopsticks'],['pizza',1,'pizza'],['rice',0,'rice'],['spaghetti',1,'pasta']]),
   cues:[['Chinatown','bin:Chinatown','Chinatown'],['Little Italy','bin:Little Italy','Little Italy','play']]},
  {say:'A Venn diagram',speech:'Sofia eats rice and bread. Her friend eats naan and bread. Bread goes in the middle, because they both eat it.',set:S.sort(['Sofia','both','friend'],[['rice',0],['bread',1],['pancakes',2,'naan']]),
   cues:[['Sofia eats','bin:Sofia','Sofia'],['in the middle','bin:both','both','play']]},
  {say:'Keep and share',speech:'In Canada, people are free to keep their own traditions and to learn about new ones. That makes our communities rich and interesting.',set:S.row(['canada','family','heart'],{labels:['Canada','families','sharing']}),
   cues:[['In Canada','canada','Canada'],['rich and interesting','heart','share']]}],
 more:{title:'Did you know?',text:'*Vancouver’s Chinatown* is one of the biggest in North America, and *Toronto* has more than one! Many Canadian cities hold street festivals where neighbourhoods share music, dancing and food with everyone.',pics:['city','music','dancer','bowl'],lead:'A Canada fact!'},
 rounds:[R.q('Where would you buy chopsticks and bowls?',['Chinatown','Little Italy','Greektown'],'Chinatown'),R.q('Where would you share a slice of pizza?',['Little Italy','Little India','Chinatown'],'Little Italy'),
  R.q('Where did Sofia see beautiful saris?',['Little India','Greektown','Little Italy'],'Little India'),R.q('What did they try in Greektown?',['souvlaki','sushi','tacos'],'souvlaki'),
  R.q('In a Venn diagram, what goes in the middle?',['things in both groups','nothing','the title'],'things in both groups'),R.sort('Sort into the Venn: Sofia, both, or friend?',['Sofia','both','friend'],[['rice',0],['bread',1],['pancakes',2,'naan']]),
  R.q('Why did Dad say Canada is interesting?',['we keep our traditions and share others','it is very cold','it has big lakes'],'we keep our traditions and share others'),R.q('A *community* is…',['a group of people who share things','a kind of food','a song'],'a group of people who share things'),
  R.tf('In Canada, people can keep their own traditions.',true),R.q('Which is a cultural neighbourhood?',['Little Italy','Big Ocean','Tall Tree'],'Little Italy'),
  R.q('In "Did you know?", which city has one of the biggest Chinatowns?',['Vancouver','Iqaluit','Halifax'],'Vancouver'),R.q('Would you like to try a new food?',['Yes!','Maybe!','I will think about it'],'Yes!')],
 tries:[['Name a food from another culture you like.','*sushi*, *tacos*, *naan*…'],['What goes in both circles for you and a friend?','foods you *both* eat']]});

/* 6 ─ Special days */
U({id:'o06',title:'Special days',strand:'Traditions and Celebrations',codes:['A1','A2'],
 guide:{goal:'Learn about special days in Canada (Canada Day, Remembrance Day) and New Year traditions of Iranian and Chinese Canadians.',words:'Canada Day, Remembrance Day, poppy, Nowruz, Lunar New Year, commemorate',ask:['What do we celebrate on July 1?','Why do people wear poppies?','What foods are part of Lunar New Year?'],home:'Find out when your family celebrates the new year and what you eat.'},
 watch:['Celebrate and remember!','On July 1, Canada has a birthday. On November 11, we remember.'],
 fig:'Flags, poppies and New Year foods.',
 page:{story:{title:'A Year of Special Days',text:'On *July 1*, it is *Canada Day*: our country’s birthday! We wave the *flag* and watch *fireworks*. On *November 11*, it is *Remembrance Day*. We wear red *poppies* and are quiet for two minutes to honour the *soldiers* who served our country. My friend Darya’s family celebrates *Nowruz*, the Iranian New Year, on the first day of spring. My friend Wei’s family celebrates *Lunar New Year* with dumplings, long noodles and steamed fish.',pics:['canada','sparkles','rose','soldier']},
  boxes:[{title:'Special days in Canada',ex:[['canada','*Canada Day*: July 1'],['sparkles','fireworks, flags'],['rose','*Remembrance Day*: Nov. 11'],['soldier','poppies for soldiers']]},
   {title:'New Year traditions',lines:['*Nowruz*: first day of spring, a table with seven "S" items: sprouts, apples, coins, garlic…','*Lunar New Year*: dumplings, long noodles for long life, steamed fish'],cols:1}],
  cards:[{q:'Why do we wear poppies?',a:'to *remember* and *respect* the soldiers who served'},{q:'Why eat long noodles at Lunar New Year?',a:'they stand for a *long life*'}],
  words:[['commemorate','to remember an important person or event'],['poppy','a red flower worn on Remembrance Day']]},
 steps:[
  {say:'Read the story',speech:'On July first, it is Canada Day, our country’s birthday, with flags and fireworks. On November eleventh, it is Remembrance Day. We wear red poppies to honour soldiers. Darya’s family celebrates Nowruz on the first day of spring. Wei’s family celebrates Lunar New Year with dumplings and noodles.',set:S.row(['canada','rose','blossom','dragon'],{labels:['Canada Day','Remembrance Day','Nowruz','Lunar New Year']}),
   cues:[['Canada Day','canada','July 1'],['Remembrance Day','rose','Nov. 11'],['Nowruz','blossom','spring'],['Lunar New Year','dragon','New Year']]},
  {say:'Canada Day',speech:'Canada Day is on July first. It is Canada’s birthday. People wave the flag, watch fireworks and have picnics.',set:S.row(['canada','sparkles','sandwich'],{labels:['flag','fireworks','picnic']}),
   cues:[['wave the flag','canada','flag'],['fireworks','sparkles','fireworks']]},
  {say:'Remembrance Day',speech:'On November eleventh, we wear poppies and stay silent for two minutes. We remember and respect the soldiers who served Canada.',set:S.row(['rose','soldier'],{labels:['poppy','soldiers']}),
   cues:[['wear poppies','rose','poppy'],['the soldiers','soldier','remember']]},
  {say:'New Year foods',speech:'Families celebrate the new year in different ways. For Nowruz, there are sprouts, apples and coins on the table. For Lunar New Year, there are dumplings, noodles and fish.',set:S.sort(['Nowruz','Lunar New Year'],[['seedling',0,'sprouts'],['dumpling',1,'dumplings'],['apple',0,'apples'],['spaghetti',1,'noodles']]),
   cues:[['Nowruz','bin:Nowruz','Nowruz'],['Lunar New Year','bin:Lunar New Year','Lunar New Year','play']]}],
 more:{title:'Did you know?',text:'The poppy became a symbol of remembrance because of a famous poem, *In Flanders Fields*, written by a Canadian doctor named *John McCrae* during the First World War. Poppies grew in the fields where soldiers rested.',pics:['rose','doctor','book','canada'],lead:'A history fact!'},
 rounds:[R.q('When is *Canada Day*?',['July 1','November 11','December 25'],'July 1'),R.q('When is *Remembrance Day*?',['November 11','July 1','March 21'],'November 11'),
  R.q('What do people wear on Remembrance Day?',['poppies','party hats','masks'],'poppies',{set:{row:['rose'],keep:true}}),R.q('On Canada Day we celebrate…',['Canada’s birthday','the first snow','Halloween'],'Canada’s birthday'),
  R.q('*Nowruz* is the New Year of…',['Iranian Canadians','Chinese Canadians','all birds'],'Iranian Canadians'),R.q('When is Nowruz?',['the first day of spring','the last day of school','New Year’s Eve'],'the first day of spring'),
  R.sort('Which New Year?',['Nowruz','Lunar New Year'],[['seedling',0,'sprouts'],['dumpling',1,'dumplings'],['coin',0,'coins'],['fish',1,'steamed fish']]),R.q('Why eat long noodles at Lunar New Year?',['for a long life','because they are crunchy','for good weather'],'for a long life'),
  R.q('Who do we honour on Remembrance Day?',['soldiers who served','singers','athletes'],'soldiers who served'),R.tf('People watch fireworks on Canada Day.',true),
  R.q('In "Did you know?", who wrote "In Flanders Fields"?',['John McCrae','a farmer','a king'],'John McCrae'),R.q('How long are people silent on Remembrance Day?',['two minutes','two hours','all day'],'two minutes')],
 tries:[['How does your family celebrate Canada Day?','*fireworks*, *picnic*, *flags*…'],['What is a poppy?','a *red flower* we wear to remember']]});

/* 7 ─ Changing traditions */
U({id:'o07',title:'Traditions change',strand:'Traditions and Celebrations',codes:['A1','A2'],
 guide:{goal:'Explain how traditions can change over generations, and give reasons for the changes (new technology, new ingredients, new ideas).',words:'change, generation, reason, technology, then, now',ask:['How has a tradition in your family changed?','Why do people send e-cards now?','What stays the same?'],home:'Ask a grandparent: How did you celebrate birthdays when you were my age? What is different now?'},
 watch:['Then and now!','Long ago, cards came by mail. Now, many people send e-cards.'],
 fig:'Traditions then and now.',
 page:{story:{title:'Pancake Day, Then and Now',text:'Long ago, on *Shrove Tuesday*, Christian families used up all their milk, butter and eggs by making *pancakes*. The day became known as *Pancake Day*. Today, families still make pancakes on Shrove Tuesday, but now they add new things like *chocolate* spread, berries, or even salmon! Other traditions change too. Some Jewish families now use *electric lights* in their menorahs, and many people send *e-cards* instead of paper cards.',pics:['pancakes','egg','chocolate','computer']},
  boxes:[{title:'Then and now',ex:[['pancakes','plain pancakes → *chocolate* and berries'],['candle','candles → *electric* menorahs'],['letter','paper cards → *e-cards*'],['candle','candles on trees → *LED lights*']],cols:2},
   {title:'Reasons for change',lines:['*new technology* (computers, LED lights)','*new ingredients* from around the world','*safety* (electric lights instead of flames)','what *families like*']}],
  cards:[{q:'Why do some people use electric menorahs?',a:'for *safety* and they last longer'},{q:'What stays the same on Pancake Day?',a:'families still eat *pancakes* together'}],
  words:[['change','to become different'],['technology','new tools and inventions']]},
 steps:[
  {say:'Read the story',speech:'Long ago, on Shrove Tuesday, families used up their milk, butter and eggs by making pancakes. Today, they add new things like chocolate and berries. Some families now use electric lights in their menorahs, and many people send e-cards.',set:S.row(['pancakes','chocolate','candle','computer'],{labels:['Pancake Day','new toppings','electric menorah','e-cards']}),
   cues:[['making pancakes','pancakes','then'],['chocolate','chocolate','now'],['electric lights','candle','now'],['e-cards','computer','now']]},
  {say:'Then and now',speech:'A tradition can stay the same in one way and change in another. Families still eat pancakes together, but the toppings have changed.',set:S.sort(['then','now'],[['letter',0,'paper card'],['computer',1,'e-card'],['candle',0,'candles'],['light bulb',1,'LED lights']]),
   cues:[['stay the same','bin:then','then'],['changed','bin:now','now','play']]},
  {say:'Reasons',speech:'Why do traditions change? New technology, like computers. New ingredients from around the world. And safety: electric lights cannot start a fire.',set:S.row(['computer','chocolate','fire'],{labels:['technology','ingredients','safety']}),
   cues:[['New technology','computer','computers'],['New ingredients','chocolate','food'],['safety','fire','safe']]},
  {say:'Your family',speech:'Ask an older relative how a celebration has changed. What is the same? What is different?',set:S.row(['grandma','child'],{labels:['then','now']}),
   cues:[['older relative','grandma','then'],['different','child','now']]}],
 more:{title:'Did you know?',text:'Long ago, people put *real candles* on Christmas trees! It looked pretty, but it was dangerous. In the 1900s, families started using *electric lights*, and today many use *LED lights* that use less energy.',pics:['evergreen','candle','light bulb','plug'],lead:'A history fact!'},
 rounds:[R.q('Another name for Shrove Tuesday is…',['Pancake Day','Canada Day','Sunday'],'Pancake Day'),R.q('Long ago, why did families make pancakes on Shrove Tuesday?',['to use up milk, butter and eggs','because of snow','to sell them'],'to use up milk, butter and eggs'),
  R.q('What new toppings do families add today?',['chocolate and berries','rocks','paper'],'chocolate and berries'),R.q('Why do some families use *electric* menorahs?',['for safety','to be noisy','to save candles for cake'],'for safety'),
  R.q('Instead of mailing paper cards, many people now send…',['e-cards','pigeons','postcards by boat'],'e-cards'),R.sort('Then or now?',['then','now'],[['letter',0,'paper card'],['computer',1,'e-card'],['candle',0,'candles on trees'],['light bulb',1,'LED lights']]),
  R.q('Which is a reason traditions change?',['new technology','the moon','sleep'],'new technology'),R.q('What stays the same on Pancake Day?',['families eat pancakes together','nobody eats','it is in July'],'families eat pancakes together'),
  R.tf('Traditions never change.',false),R.q('Who could tell you how traditions were long ago?',['a grandparent','a baby','a goldfish'],'a grandparent'),
  R.q('In "Did you know?", what did people put on Christmas trees long ago?',['real candles','LED lights','balloons'],'real candles'),R.q('Why use LED lights?',['they use less energy','they are hot','they are loud'],'they use less energy')],
 tries:[['Name a tradition that changed in your family.','*video calls* with family far away…'],['Why might a tradition stay the same?','because families *love* it']]});

/* 8 ─ Celebrating winter */
U({id:'o08',title:'Winter celebrations',strand:'Traditions and Celebrations',codes:['A1','A2','A3'],
 guide:{goal:'Learn how families celebrate in winter (Kwanzaa, Christmas and others), and how decorations and traditions change across generations.',words:'Kwanzaa, kinara, Christmas, decoration, generation',ask:['When is Kwanzaa?','How many candles are lit for Kwanzaa?','How did your grandparents decorate long ago?'],home:'Make a winter decoration the way a grandparent did when they were young.'},
 watch:['Light the seven candles!','During Kwanzaa, families light one candle each day for seven days.'],
 fig:'Candles, gifts and decorations of winter celebrations.',
 page:{story:{title:'Seven Candles',text:'Every winter, Jamal’s family celebrates *Kwanzaa*, from *December 26 to January 1*. Kwanzaa honours *African heritage*. Each day, they light one candle in the *kinara*: there are *seven* candles, in black, red and green. Each candle stands for an idea, like *unity* and *creativity*. At the end, there is a big *feast*, and children get *gifts* that are often handmade or books. "My favourite part is telling family stories," Jamal says.',pics:['candle','gift','book','family']},
  boxes:[{title:'Kwanzaa',lines:['December 26 to January 1','*7* candles in a *kinara*','a big *feast*','*gifts* for children','honours *African heritage*'],cols:1},
   {title:'Decorations change',ex:[['candle','grandparents: *candles*'],['popcorn','grandparents: *popcorn strings*'],['light bulb','parents: *plastic bulbs*'],['sparkles','now: *LED lights*']],cols:2}],
  cards:[{q:'How many days is Kwanzaa?',a:'*seven* days'},{q:'What colours are the Kwanzaa candles?',a:'*black, red and green*'}],
  words:[['kinara','the candle holder for Kwanzaa'],['heritage','traditions passed down from the past']]},
 steps:[
  {say:'Read the story',speech:'Jamal’s family celebrates Kwanzaa, from December twenty-sixth to January first. Each day, they light one candle in the kinara: seven candles, in black, red and green. At the end, there is a feast and gifts.',set:S.row(['candle','gift','book','family'],{labels:['kinara','gifts','books','family stories']}),
   cues:[['one candle','candle','7 candles'],['gifts','gift','gifts'],['a feast','family','feast']]},
  {say:'Things to do',speech:'During Kwanzaa, families light candles, have a feast and give children gifts, like books or handmade crafts.',set:S.row(['candle','cake','gift'],{labels:['light candles','have a feast','give gifts']}),
   cues:[['light candles','candle','candles'],['have a feast','cake','feast'],['give children gifts','gift','gifts']]},
  {say:'Decorations then and now',speech:'Grandparents decorated with candles and popcorn strings. Parents used plastic bulbs. Today, many families use LED lights.',set:S.order(['candle','light bulb','sparkles']),
   cues:[['Grandparents','candle','long ago'],['Parents','light bulb','later'],['Today','sparkles','now','play']]},
  {say:'Your winter celebration',speech:'What does your family do in winter? Do you light candles, sing songs, or eat a special meal?',set:S.row(['snowflake','music','soup'],{labels:['winter','songs','meal']}),
   cues:[['sing songs','music','songs'],['a special meal','soup','meal']]}],
 more:{title:'Did you know?',text:'Kwanzaa was started in 1966 by *Dr. Maulana Karenga*. The name comes from a Swahili phrase that means "*first fruits* of the harvest." That is why fruits and vegetables are part of the Kwanzaa table.',pics:['banana','apple','corn','book'],lead:'A celebration fact!'},
 rounds:[R.q('When does Kwanzaa begin?',['December 26','July 1','March 21'],'December 26'),R.q('How many candles are in a Kwanzaa kinara?',['seven','eight','three'],'seven',{set:{row:['candle'],keep:true}}),
  R.q('What colours are the Kwanzaa candles?',['black, red and green','blue and white','orange and purple'],'black, red and green'),R.q('Kwanzaa honours…',['African heritage','the first snow','summer'],'African heritage'),
  R.q('Which is one thing families do during Kwanzaa?',['have a feast','go swimming','plant a garden'],'have a feast'),R.order('Put the decorations in order from long ago to now.',['candle','light bulb','sparkles']),
  R.q('What was Jamal’s favourite part?',['telling family stories','opening gifts','eating cake'],'telling family stories'),R.q('What gifts do children often get?',['books or handmade gifts','cars','phones'],'books or handmade gifts'),
  R.tf('Kwanzaa lasts seven days.',true),R.q('What did grandparents use to decorate long ago?',['candles and popcorn strings','LED lights','robots'],'candles and popcorn strings'),
  R.q('In "Did you know?", what does Kwanzaa’s name mean?',['first fruits of the harvest','winter night','big candle'],'first fruits of the harvest'),R.q('A *kinara* is…',['a candle holder','a song','a hat'],'a candle holder')],
 tries:[['Name a winter celebration.','*Kwanzaa*, *Christmas*, *Hanukkah*, *Lunar New Year*…'],['How do you decorate in winter?','*lights*, *snowflakes*, *candles*…']]});

/* 9 ─ Mapping traditions: First Nations in Ontario */
U({id:'o09',title:'Mapping our traditions',strand:'Traditions and Celebrations',codes:['A1','A2','A3'],
 guide:{goal:'Use a map to find where First Nations communities lived and still live in Ontario, and learn about the powwow as a living tradition.',words:'First Nations, Ojibway (Anishinaabe), Huron-Wendat, settlement, map, powwow, ancestors',ask:['Which First Nations lived near your community?','What is a powwow?','Why do maps help us learn about traditions?'],home:'Find out whose traditional land your school is on. Many schools share a land acknowledgement.'},
 watch:['Find it on the map!','The Ojibway live around Lake Superior, near where their ancestors lived.'],
 fig:'A map grid of Ontario with communities past and present.',
 page:{story:{title:'The Map in Our Classroom',text:'Our class looked at a big *map of Ontario*. Long before cities like *Toronto* and *Thunder Bay* were built, many *First Nations* lived here. The *Huron-Wendat* lived near where Barrie is today. The *Ojibway* (Anishinaabe) lived around *Lake Superior*, and many still live there. Every year, the *Pic River First Nation* holds a *powwow*, where people sing, drum and dance to give thanks to the *Creator* for all that Mother Earth provides.',pics:['map','canada','drum','dancer']},
  boxes:[{title:'Past and present',text:'First Nations peoples have lived on this land for thousands of years. Some communities moved; others still live where their *ancestors* lived.',lines:['Huron-Wendat: near *Barrie* (past)','Ojibway: around *Lake Superior* (past and present)','Today: *Sudbury*, *Thunder Bay*, *Toronto*…']},
   {title:'Powwow',lines:['a *ceremony* and celebration','*singing*, *drumming*, *dancing*','giving *thanks* to the Creator','held all across *Canada*; visitors are welcome']}],
  cards:[{q:'What is a powwow?',a:'a First Nations *gathering* with singing, drumming and dancing'},{q:'What are ancestors?',a:'family members who lived *long ago*'}],
  words:[['ancestors','family members from long ago'],['ceremony','a special event with traditions']]},
 steps:[
  {say:'Read the story',speech:'Long before cities were built, many First Nations lived in Ontario. The Huron-Wendat lived near where Barrie is today. The Ojibway lived around Lake Superior, and many still live there. Every year, the Pic River First Nation holds a powwow to sing, drum, dance and give thanks.',set:{grid:{rows:3,cols:4,items:{A1:'house',B3:'house',C3:'city',A2:'drum'}}},
   cues:[['Lake Superior','house','Ojibway'],['Barrie','city','Huron-Wendat'],['a powwow','drum','powwow']]},
  {say:'Reading a map',speech:'A map shows where places are. Rows go across and columns go down. We can find the square where a community is.',set:{grid:{rows:3,cols:4,items:{B2:'house',A4:'tree',C1:'water'}}},
   cues:[['A map shows','house','B2']]},
  {say:'The powwow',speech:'At a powwow, people gather in a big circle. Drummers drum and sing, and dancers in colourful regalia dance. It is a way to give thanks and to keep traditions alive.',set:S.row(['drum','dancer','people'],{labels:['drum and song','dancers','gathering']}),
   cues:[['Drummers drum','drum','drum'],['dancers','dancer','dance'],['give thanks','people','thanks']]},
  {say:'Living traditions',speech:'First Nations traditions are not only from long ago. They are alive today, in communities across Canada, and people from around the world are welcome at many powwows.',set:S.row(['canada','heart'],{labels:['across Canada','welcome']}),
   cues:[['alive today','canada','today'],['welcome','heart','welcome']]}],
 more:{title:'Did you know?',text:'Many place names in Ontario come from *Indigenous* languages! *Toronto* may come from a Mohawk word about trees standing in water, and *Ontario* comes from a word meaning "*beautiful lake*" or "great lake."',pics:['city','water','tree','map'],lead:'A place-name fact!'},
 rounds:[R.grid('Tap the square where the drum is (the powwow).',{rows:3,cols:4,items:{A2:'drum',B4:'tree',C1:'house'}},'A2'),R.grid('Tap the city.',{rows:3,cols:4,items:{B3:'city',A1:'house'}},'B3'),
  R.q('Which First Nation lives around Lake Superior?',['Ojibway (Anishinaabe)','Inuit','Haida'],'Ojibway (Anishinaabe)'),R.q('Near which city did the Huron-Wendat live?',['Barrie','Vancouver','Halifax'],'Barrie'),
  R.q('What happens at a powwow?',['singing, drumming and dancing','skating races','a car show'],'singing, drumming and dancing'),R.q('At a powwow, people give thanks to the…',['Creator','teacher','mayor'],'Creator'),
  R.q('What are *ancestors*?',['family members from long ago','new neighbours','pets'],'family members from long ago'),R.q('Who holds a powwow every year in the story?',['Pic River First Nation','a hockey team','a school band'],'Pic River First Nation'),
  R.tf('First Nations traditions are still alive today.',true),R.q('Where are powwows held?',['all across Canada','only in one town','only on the moon'],'all across Canada'),
  R.q('In "Did you know?", what does "Ontario" mean?',['beautiful lake or great lake','big rock','cold wind'],'beautiful lake or great lake'),R.q('A map helps us learn…',['where communities are','what time it is','how to bake'],'where communities are')],
 tries:[['Whose traditional land is your school on?','ask your teacher about the *land acknowledgement*'],['What is a powwow?','a celebration with *drums*, *songs* and *dance*']]});

/* 10 ─ Thanksgiving */
U({id:'o10',title:'Thanksgiving then and now',strand:'Traditions and Celebrations',codes:['A1','A2'],
 guide:{goal:'Learn how early Thanksgivings in Canada were celebrated and compare them with Thanksgiving today.',words:'Thanksgiving, harvest, explorer, feast, settlers, then and now',ask:['Who held an early thanksgiving in Canada?','What did early settlers eat?','How is your Thanksgiving different?'],home:'At Thanksgiving dinner, everyone names one thing they are thankful for.'},
 watch:['Give thanks!','Long ago, people gave thanks for a safe trip and a good harvest. We still give thanks today.'],
 fig:'Thanksgiving foods then and now.',
 page:{story:{title:'Alexandra’s Diary, Long Ago',text:'*Dear Diary,* My father caught the biggest *turkey* we have ever seen! Mother used *maple syrup* from our trees to sweeten the *cranberry* sauce. My brother and I gathered *squash* and *corn* from the garden. We have no flour or sugar for pies, but I can smell the turkey roasting. My stomach is growling! *Yours, Alexandra.* Long ago, explorers and settlers held feasts to give thanks for a safe trip or a good *harvest*.',pics:['turkey','maple leaf','corn','pumpkin']},
  boxes:[{title:'Early thanksgivings',lines:['*1578*: explorer *Martin Frobisher* gave thanks for a safe trip, in the Arctic','*1606*: *Samuel de Champlain* held feasts of thanks with his men and First Nations neighbours','early feasts used food people *hunted*, *gathered* and *grew*'],cols:1},
   {title:'Then and now',lines:['then: turkey they *hunted*','now: turkey from the *store*','then: maple syrup from *trees*','now: pumpkin pie with *flour and sugar*']}],
  cards:[{q:'When is Thanksgiving in Canada?',a:'the *second Monday in October*'},{q:'What is a harvest?',a:'*gathering crops* when they are ready'}],
  words:[['harvest','gathering crops when they are ripe'],['settler','a person who comes to live in a new place']]},
 steps:[
  {say:'Read the diary',speech:'Dear Diary. My father caught the biggest turkey! Mother used maple syrup to sweeten the cranberry sauce. We gathered squash and corn from the garden. Long ago, people held feasts to give thanks for a safe trip or a good harvest.',set:S.row(['turkey','maple leaf','corn','pumpkin'],{labels:['turkey','maple syrup','corn','squash']}),
   cues:[['the biggest turkey','turkey','hunted'],['maple syrup','maple leaf','from trees'],['squash and corn','corn|pumpkin','from the garden']]},
  {say:'Early explorers',speech:'In 1578, explorer Martin Frobisher gave thanks for a safe trip across the ocean. Later, Samuel de Champlain held feasts of thanks with his men and First Nations neighbours.',set:S.row(['ship','turkey','people'],{labels:['safe trip','feast','sharing']}),
   cues:[['a safe trip','ship','1578'],['feasts of thanks','turkey','feast'],['First Nations neighbours','people','sharing']]},
  {say:'Food and how to get it',speech:'Long ago, families hunted turkey, tapped maple trees for syrup and grew squash and corn. Today, most families buy food at the store.',set:S.sort(['then','now'],[['turkey',0,'hunted turkey'],['shopping cart',1,'store turkey'],['maple leaf',0,'tree syrup'],['pie',1,'pumpkin pie']]),
   cues:[['Long ago','bin:then','then'],['Today','bin:now','now','play']]},
  {say:'Thanksgiving today',speech:'Today, Canadians celebrate Thanksgiving on the second Monday in October. Families share a meal and say what they are thankful for.',set:S.row(['family','pie','heart'],{labels:['family','pie','thankful']}),
   cues:[['second Monday in October','family','October'],['thankful','heart','thanks']]}],
 more:{title:'Did you know?',text:'Canada’s Thanksgiving comes about *six weeks earlier* than Thanksgiving in the United States! One reason is that Canada is farther north, so the harvest is ready earlier, before the cold weather arrives.',pics:['canada','pumpkin','snowflake','calendar'],lead:'A Canada fact!'},
 rounds:[R.q('When is Thanksgiving in Canada?',['the second Monday in October','July 1','December 25'],'the second Monday in October'),R.q('Who gave thanks for a safe trip in 1578?',['Martin Frobisher','Samuel de Champlain','Alexandra'],'Martin Frobisher'),
  R.q('Long ago, why did people hold feasts of thanks?',['for a safe trip or good harvest','for a new phone','for snow'],'for a safe trip or good harvest'),R.q('What did Alexandra’s father catch?',['a turkey','a fish','a deer'],'a turkey',{set:{row:['turkey'],keep:true}}),
  R.q('What sweetened the cranberry sauce?',['maple syrup','sugar from the store','honey cake'],'maple syrup'),R.q('Why were there no pies?',['no flour or sugar','no ovens','nobody liked pie'],'no flour or sugar'),
  R.sort('Then or now?',['then','now'],[['turkey',0,'hunted turkey'],['shopping cart',1,'store turkey'],['maple leaf',0,'syrup from trees'],['pie',1,'pumpkin pie']]),R.q('What is a *harvest*?',['gathering ripe crops','a kind of hat','a holiday song'],'gathering ripe crops'),
  R.tf('Alexandra gathered squash and corn.',true),R.q('Who held feasts of thanks with First Nations neighbours?',['Samuel de Champlain','Martin Frobisher','Johnny Appleseed'],'Samuel de Champlain'),
  R.q('In "Did you know?", why is Canada’s Thanksgiving earlier?',['the harvest is ready earlier in the north','it is warmer','there is no snow'],'the harvest is ready earlier in the north'),R.q('What do families share at Thanksgiving today?',['a meal and what they are thankful for','homework','umbrellas'],'a meal and what they are thankful for')],
 tries:[['What are you thankful for?','my *family*, my *friends*, my *pet*…'],['Name a Thanksgiving food.','*turkey*, *pumpkin pie*, *cranberries*']]});
})();
